58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
65	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        validateRequiredFields(ownerFieldsDto);
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
120	        rejectDuplicateTelephone(telephone);
121	        owner.setTelephone(telephone);
122	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
135	     * offending field so the client learns about all of them at once.
136	     *
137	     * @param ownerFieldsDto the submitted owner fields
138	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
139	     *                                     missing or blank
140	     */
141	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
142	        List<String> errors = new ArrayList<>();
143	        if (isBlank(ownerFieldsDto.getFirstName())) {
144	            errors.add("firstName");
145	        }
146	        if (isBlank(ownerFieldsDto.getLastName())) {
147	            errors.add("lastName");
148	        }
149	        if (isBlank(ownerFieldsDto.getAddress())) {
150	            errors.add("address");
151	        }
152	        if (isBlank(ownerFieldsDto.getCity())) {
153	            errors.add("city");
154	        }
155	        if (isBlank(ownerFieldsDto.getTelephone())) {
156	            errors.add("telephone");
157	        }
158	        if (!errors.isEmpty()) {
159	            throw new MissingOwnerFieldsException(errors);
160	        }
161	    }
162	
163	    private boolean isBlank(String value) {
164	        return value == null || value.isBlank();
165	    }
166	
167	    /**
168	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
169	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
170	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
171	     * followed by 8 to 15 digits.
172	     *
173	     * @param telephone the raw telephone value as submitted
174	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
175	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
176	     */
177	    private String normalizeTelephone(String telephone) {
178	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
179	        String nationalSignificantNumber;
180	        if (cleaned.startsWith("+")) {
181	            nationalSignificantNumber = cleaned.substring(1);
182	        } else {
183	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
184	            nationalSignificantNumber = "61" + national;
185	        }
186	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
187	            throw new InvalidTelephoneException(telephone);
188	        }
189	        return "+" + nationalSignificantNumber;
190	    }
191	
192	    /**
193	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
194	     * value is treated as absent and returns {@code null}); when present the value must be a
195	     * syntactically valid address, and is stored and returned lower-cased.
196	     *
197	     * @param email the raw email value as submitted, may be {@code null}
198	     * @return the lower-cased email, or {@code null} when none was supplied
199	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
200	     */
201	    private String normalizeEmail(String email) {
202	        if (email == null || email.isBlank()) {
203	            return null;
204	        }
205	        String normalized = email.trim().toLowerCase();
206	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
207	            throw new InvalidEmailException(email);
208	        }
209	        return normalized;
210	    }
211	
212	    /**
213	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
214	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
215	     * comparison, so numbers that differ only in formatting still count as duplicates.
216	     *
217	     * @param e164Telephone the E.164 telephone of the owner being created
218	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
219	     */
220	    private void rejectDuplicateTelephone(String e164Telephone) {
221	        boolean inUse = this.clinicService.findAllOwners().stream()
222	            .map(Owner::getTelephone)
223	            .filter(existing -> existing != null)
224	            .map(this::toComparableTelephone)
225	            .filter(existing -> existing != null)
226	            .anyMatch(e164Telephone::equals);
227	        if (inUse) {
228	            throw new DuplicateTelephoneException(e164Telephone);
229	        }
230	    }
231	
232	    /**
233	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
234	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
235	     * than aborting the whole create.
236	     */
237	    private String toComparableTelephone(String telephone) {
238	        try {
239	            return normalizeTelephone(telephone);
240	        } catch (InvalidTelephoneException ex) {
241	            return null;
242	        }
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
