247	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        currentOwner.setAddress(ownerFieldsDto.getAddress());
253	        currentOwner.setCity(ownerFieldsDto.getCity());
254	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
255	        currentOwner.setLastName(ownerFieldsDto.getLastName());
256	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
257	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
258	        this.clinicService.saveOwner(currentOwner);
259	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Transactional
264	    @Override
265	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner == null) {
268	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	        }
270	        this.clinicService.deleteOwner(owner);
271	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner == null) {
279	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	        }
281	        HttpHeaders headers = new HttpHeaders();
282	        Pet pet = petMapper.toPet(petFieldsDto);
283	        owner.setId(ownerId);
284	        pet.setOwner(owner);
285	        pet.getType().setName(null);
286	        this.clinicService.savePet(pet);
287	        PetDto petDto = petMapper.toPetDto(pet);
288	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
289	            .buildAndExpand(pet.getId()).toUri());
290	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
296	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
297	        if (currentOwner != null) {
298	            Pet currentPet = this.clinicService.findPetById(petId);
299	            if (currentPet != null) {
300	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
301	                currentPet.setName(petFieldsDto.getName());
302	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
303	                this.clinicService.savePet(currentPet);
304	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
313	        HttpHeaders headers = new HttpHeaders();
314	        Visit visit = visitMapper.toVisit(visitFieldsDto);
315	        Pet pet = new Pet();
316	        pet.setId(petId);
317	        visit.setPet(pet);
318	        this.clinicService.saveVisit(visit);
319	        VisitDto visitDto = visitMapper.toVisitDto(visit);
320	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
321	            .buildAndExpand(visit.getId()).toUri());
322	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
323	    }
